import React, { useState } from "react";
import { Text, useInput } from "ink";
import { theme } from "../theme.ts";

interface InputProps {
  onSubmit: (value: string) => void;
  onChange?: (value: string) => void;
  history: string[];
}

export function Input({ onSubmit, onChange, history }: InputProps): React.ReactElement {
  const [value, setValue] = useState("");
  const [cursor, setCursor] = useState(0);
  const [histIdx, setHistIdx] = useState(-1);
  const [stash, setStash] = useState("");

  const update = (next: string, nextCursor: number) => {
    setValue(next);
    setCursor(Math.max(0, Math.min(nextCursor, next.length)));
    onChange?.(next);
  };

  useInput((input, key) => {
    if (key.return) {
      const trimmed = value.trim();
      if (!trimmed) return;
      update("", 0);
      setHistIdx(-1);
      onSubmit(trimmed);
      return;
    }
    if (key.upArrow) {
      if (history.length === 0) return;
      const next = histIdx === -1 ? history.length - 1 : Math.max(0, histIdx - 1);
      if (histIdx === -1) setStash(value);
      setHistIdx(next);
      update(history[next], history[next].length);
      return;
    }
    if (key.downArrow) {
      if (histIdx === -1) return;
      const next = histIdx + 1;
      if (next >= history.length) {
        setHistIdx(-1);
        update(stash, stash.length);
      } else {
        setHistIdx(next);
        update(history[next], history[next].length);
      }
      return;
    }
    if (key.leftArrow) {
      setCursor((c) => Math.max(0, c - 1));
      return;
    }
    if (key.rightArrow) {
      setCursor((c) => Math.min(value.length, c + 1));
      return;
    }
    if (key.backspace || key.delete) {
      if (cursor === 0) return;
      update(value.slice(0, cursor - 1) + value.slice(cursor), cursor - 1);
      return;
    }
    if (key.ctrl && input === "a") {
      setCursor(0);
      return;
    }
    if (key.ctrl && input === "e") {
      setCursor(value.length);
      return;
    }
    if (key.ctrl && input === "u") {
      update("", 0);
      return;
    }
    if (key.ctrl && input === "w") {
      const before = value.slice(0, cursor).replace(/\S+\s*$/, "");
      update(before + value.slice(cursor), before.length);
      return;
    }
    if (key.ctrl || key.meta || key.escape || key.tab) return;
    if (input) {
      const clean = input.replace(/[\x00-\x08\x0b-\x1f\x7f]/g, "");
      if (!clean) return;
      update(value.slice(0, cursor) + clean + value.slice(cursor), cursor + clean.length);
    }
  });

  const before = value.slice(0, cursor);
  const at = value[cursor] ?? " ";
  const after = value.slice(cursor + 1);

  return (
    <Text>
      <Text color={theme.orange} bold>
        ❯{" "}
      </Text>
      <Text>{before}</Text>
      <Text inverse>{at}</Text>
      <Text>{after}</Text>
    </Text>
  );
}
